const segScore = (run) => { const n = run.length, best = new Array(n + 1).fill(-Infinity); best[0] = 0; for (let i = 1; i <= n; i++) { best[i] = best[i - 1] + UNKNOWN_CHAR; for (let j = Math.max(0, i - 16); j < i; j++) { const s = wordScore(run.slice(j, i)); if (s > 0 && best[j] + s - 0.5 > best[i]) best[i] = best[j] + s - 0.5; } } return best[n]; };
export function splitGameName(file) {
  let s = String(file).replace(/\.[a-z0-9]+$/i, "");
  if (/^cl/.test(s)) s = s.slice(2); // the collection's "cl" prefix
  if (FIXED[s.toLowerCase()]) return FIXED[s.toLowerCase()];
  s = s.replace(/[_\-+]+/g, " ").replace(/(?<!\d)\.|\.(?!\d)/g, " ").replace(/\s+/g, " ").trim();
  if (!s) return String(file);
  const out = [];
  for (const chunk of s.split(" ")) {
    if (/^[\d.]+$/.test(chunk)) { out.push(chunk); continue; } // 1.2.6
    let rest = chunk;
    const ord = rest.match(/^(\d+(?:st|nd|rd|th))(?=[a-z])/i); // 4thandgoal -> 4th, then "andgoal"
    if (ord) { out.push(ord[1]); rest = rest.slice(ord[1].length); }
    const spaced = rest
      .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2").replace(/([a-z])([A-Z])/g, "$1 $2")
      .replace(/(\d)([A-Za-z])/g, "$1 $2").replace(/([A-Za-z])(\d)/g, "$1 $2");
    const parts = spaced.split(" ");
    for (let k = 0; k < parts.length; k++) {
      const p = parts[k], nx = parts[k + 1] || "";
      if (/^v$/i.test(p) && /^\d+$/.test(parts[k - 1] || "") && /^\d+$/.test(nx)) { out[out.length - 1] += "v" + nx; k++; continue; } // 1v1
      if (/^\d+$/.test(p) && /^d$/.test(nx)) { out.push(p + "D"); k++; continue; } // snowrider3d -> 3D
      if (/^\d+$/.test(p) && /^d[a-z]{3,}$/i.test(nx)) { // 3dpinball... : is it "3D pinball" or "3 dpinball"?
        const low = nx.toLowerCase();
        if (segScore(low.slice(1)) > segScore(low) + 3) { out.push(p + "D", ...segment(low.slice(1))); k++; continue; }
      }
      if (/^[a-z]+$/.test(p) && p.length > 3) out.push(...segment(p)); else out.push(p);
    }
  }
  return out.map((w, i) => (ACRONYM.has(w.toLowerCase()) ? w.toUpperCase() : /^[a-z]/.test(w) ? (i > 0 && SMALL.has(w) ? w : w[0].toUpperCase() + w.slice(1)) : w)).join(" ");
}
